BEGIN;
CREATE TABLE public.sales_transitions (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "EventId" integer NOT NULL REFERENCES public.events(id) ON DELETE RESTRICT,
    "ShowtimeId" integer NULL REFERENCES public.showtimes(id) ON DELETE RESTRICT,
    "ActorUserId" integer NOT NULL REFERENCES public."Users"("Id") ON DELETE RESTRICT,
    "FromStatus" varchar(20) NOT NULL,
    "ToStatus" varchar(20) NOT NULL,
    "OccurredAtUtc" timestamptz NOT NULL
);
CREATE INDEX "IX_sales_transitions_EventId_OccurredAtUtc" ON public.sales_transitions("EventId", "OccurredAtUtc");
COMMIT;
